import { Component, OnInit } from '@angular/core';

@Component({
  selector: 'app-random-picker',
  templateUrl: './random-picker.component.html',
  styleUrls: ['./random-picker.component.scss']
})
export class RandomPickerComponent implements OnInit {

  namesText = 'علی محمدی\nسارا رضایی\nحسین حسینی\nمریم کریمی\nامیرعلی احمدی\nفاطمه موسوی\nمهدی نوری\nزهرا ابراهیمی\nطاها قاسم‌پور\nنازنین صادقی';
  namesList: string[] = [];

  newName = '';
  isSpinning = false;
  selectedWinner: string | null = null;
  history: string[] = [];

  // تنظیمات
  removeAfterPick = false;

  ngOnInit(): void {
    this.parseNames();
  }

  parseNames(): void {
    this.namesList = this.namesText
      .split('\n')
      .map(n => n.trim())
      .filter(n => n.length > 0);
  }

  addSingleName(): void {
    if (this.newName && this.newName.trim()) {
      this.namesList.push(this.newName.trim());
      this.namesText = this.namesList.join('\n');
      this.newName = '';
    }
  }

  removeName(index: number): void {
    this.namesList.splice(index, 1);
    this.namesText = this.namesList.join('\n');
  }

  spin(): void {
    if (this.namesList.length === 0 || this.isSpinning) { return; }

    this.isSpinning = true;
    this.selectedWinner = null;

    let counter = 0;
    const maxSpins = 25;
    const interval = setInterval(() => {
      const randomIdx = Math.floor(Math.random() * this.namesList.length);
      this.selectedWinner = this.namesList[randomIdx];
      counter++;

      if (counter >= maxSpins) {
        clearInterval(interval);
        this.isSpinning = false;
        if (this.selectedWinner) {
          this.history.unshift(this.selectedWinner);
          if (this.removeAfterPick) {
            const idx = this.namesList.indexOf(this.selectedWinner);
            if (idx > -1) {
              this.namesList.splice(idx, 1);
              this.namesText = this.namesList.join('\n');
            }
          }
        }
      }
    }, 100);
  }

  clearHistory(): void {
    this.history = [];
  }
}
